{"cmd":"python3 -c "
import csv
# Verify customer counts
loyalty_customers = {}
with open('data/loyalty_customers.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        ln_raw = row['Loyalty_Number'].strip()
        try:
            ln = int(float(ln_raw))
        except:
            continue
        tier_raw = row['Loyalty_Tier'].strip()
        tier_lower = tier_raw.lower()
        if tier_lower in ('gold', 'goald'):
            tier = 'Gold'
        elif tier_lower in ('silver', 'sliver'):
            tier = 'Silver'
        elif tier_lower in ('bronze', 'bronz'):
            tier = 'Bronze'
        else:
            tier = None
        loyalty_customers[ln] = tier

from collections import Counter
tier_counts = Counter(loyalty_customers.values())
for t,c in tier_counts.items():
    print(f'{t}: {c}')

# Check: number of unique loyalty numbers in 2023/2024 transactions by tier
tier_custs = {'Gold': set(), 'Silver': set(), 'Bronze': set(), None: set()}
with open('data/transactions.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        date_str = row['Transaction_Date'].strip()
        year = date_str.split(', ')[-1]
        if year not in ('2023', '2024'):
            continue
        ln_raw = row['Loyalty_Number'].strip()
        if not ln_raw:
            continue
        try:
            ln = int(float(ln_raw))
        except:
            continue
        tier = loyalty_customers.get(ln)
        tier_custs[tier].add(ln)

for t in ('Gold','Silver','Bronze',None):
    print(f'{t} unique customers in tx: {len(tier_custs[t])}')
""}

